#include <stdio.h>
int linearSearch(int arr[], int n, int target) {
    for (int i = 0; i < n; i++) if (arr[i] == target) return i;
    return -1;
}
int main() {
    int arr[] = {4, 2, 7, 1, 9, 3};
    printf("%d\n", linearSearch(arr, 6, 7));
    printf("%d\n", linearSearch(arr, 6, 5));
    return 0;
}

cpp.code:
#include <iostream>
#include <vector>
using namespace std;
int linearSearch(const vector<int>& arr, int target) {
    for (int i = 0; i < (int)arr.size(); i++) if (arr[i] == target) return i;
    return -1;
}
int main() {
    vector<int> arr = {4, 2, 7, 1, 9, 3};
    cout << linearSearch(arr, 7) << endl;
    cout << linearSearch(arr, 5) << endl;
    return 0;
}

